#include <stdlib.h>

typedef struct {
    long long y1, y2, a;
    int id;
} Line;

static int compare_start(const void *p1, const void *p2) {
    const Line *x = p1;
    const Line *y = p2;

    if (x->y1 < y->y1) return -1;
    if (x->y1 > y->y1) return 1;
    if (x->a > y->a) return -1;
    if (x->a < y->a) return 1;
    return x->id - y->id;
}

static int compare_end(const void *p1, const void *p2) {
    const Line *x = p1;
    const Line *y = p2;

    if (x->y2 < y->y2) return -1;
    if (x->y2 > y->y2) return 1;
    if (x->a < y->a) return -1;
    if (x->a > y->a) return 1;
    return x->id - y->id;
}

