    int n;
    long long x1, x2;

    if (scanf("%d %lld %lld", &n, &x1, &x2) != 3) return 0;

    Line *start = malloc((size_t)n * sizeof(Line));
    Line *end = malloc((size_t)n * sizeof(Line));
    int *rank = malloc((size_t)n * sizeof(int));
    long long *fenwick = calloc((size_t)n + 1, sizeof(long long));

