        start[i].a = end[i].a = a;
        start[i].y1 = a * x1 + b;
        start[i].y2 = a * x2 + b;
        start[i].id = end[i].id = i;
    }

    qsort(start, (size_t)n, sizeof(Line), compare_start);
    qsort(end, (size_t)n, sizeof(Line), compare_end);

    for (int i = 0; i < n; ++i)
        rank[end[i].id] = i + 1;

    long long inversions = 0;
    for (int i = 0; i < n; ++i) {
        int r = rank[start[i].id];
        long long at_most = 0;

        for (int p = r; p > 0; p -= p & -p)
            at_most += fenwick[p];

        inversions += i - at_most;

        for (int p = r; p <= n; p += p & -p)
            fenwick[p]++;
    }

    printf("%lld\n", inversions);

    free(start);
    free(end);
    free(rank);
    free(fenwick);
    return 0;
}
